import { DndContext, DragEndEvent, useSensor, useSensors, PointerSensor } from '@dnd-kit/core';
import { useState, useEffect } from 'react';

import LoadingSpinner from '../components/common/LoadingSpinner';
import { toast } from '../components/common/Toast';
import SEO from '../components/SEO';
import AssignmentDisplay from '../components/TagManagement/AssignmentDisplay';
import ContentList from '../components/TagManagement/ContentList';
import TagList from '../components/TagManagement/TagList';
import type { Tag } from '../hooks/useTags';
import { supabase } from '../lib/supabase/client';
import type { ContentItem } from '../types/common';

export default function TagManagementPage() {
  const [tags, setTags] = useState<Tag[]>([]);
  const [projects, setProjects] = useState<ContentItem[]>([]);
  const [articles, setArticles] = useState<ContentItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  // Configure DnD sensors
  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: {
        distance: 8,
      },
    })
  );

  useEffect(() => {
    async function fetchData() {
      try {
        setIsLoading(true);

        // Fetch tags
        const { data: tagsData, error: tagsError } = await supabase
          .from('tags')
          .select('*')
          .order('name');

        if (tagsError) throw tagsError;
        setTags(
          (tagsData || []).map(t => ({
            ...t,
            category: t.category ?? undefined,
            color: t.color ?? undefined,
          }))
        );

        // Fetch projects with their tags
        const { data: projectsData, error: projectsError } = await supabase
          .from('content')
          .select(
            `
            id,
            title,
            tags
          `
          )
          .eq('type', 'project')
          .eq('published', true);

        if (projectsError) throw projectsError;
        setProjects(projectsData || []);

        // Fetch articles with their tags
        const { data: articlesData, error: articlesError } = await supabase
          .from('content')
          .select(
            `
            id,
            title,
            tags
          `
          )
          .eq('type', 'article')
          .eq('published', true);

        if (articlesError) throw articlesError;
        setArticles(articlesData || []);
      } catch (error) {
        console.error('Error fetching data:', error);
        toast.error('Failed to load data');
      } finally {
        setIsLoading(false);
      }
    }

    fetchData();
  }, []);

  const handleDragEnd = async (event: DragEndEvent) => {
    const { active, over } = event;

    if (!over) return;

    const tagId = active.id;
    const [type, contentId] = over.id.toString().split(':');

    try {
      // Get current content item
      const { data: currentContent, error: fetchError } = await supabase
        .from('content')
        .select('tags')
        .eq('id', contentId)
        .single();

      if (fetchError) throw fetchError;

      // Get tag name
      const tag = tags.find(t => t.id === tagId);
      if (!tag) throw new Error('Tag not found');

      // Add tag if not already present
      const currentTags = currentContent.tags || [];
      if (!currentTags.includes(tag.name)) {
        const updatedTags = [...currentTags, tag.name];

        // Update content
        const { error: updateError } = await supabase
          .from('content')
          .update({ tags: updatedTags })
          .eq('id', contentId);

        if (updateError) throw updateError;

        // Refresh data
        const { data, error: refreshError } = await supabase
          .from('content')
          .select(
            `
            id,
            title,
            tags
          `
          )
          .eq('id', contentId)
          .single();

        if (refreshError) throw refreshError;

        // Update state
        if (type === 'project') {
          setProjects(prev => prev.map(p => (p.id === contentId ? data : p)));
        } else {
          setArticles(prev => prev.map(a => (a.id === contentId ? data : a)));
        }

        toast.success('Tag assigned successfully');
      }
    } catch (error) {
      console.error('Error assigning tag:', error);
      toast.error('Failed to assign tag');
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen pt-24">
        <div className="container mx-auto px-6">
          <LoadingSpinner />
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen pt-24 pb-16">
      <SEO
        title="Tag Management | REWI.RE"
        description="Manage content tags and categories"
        path="/tag-management"
        type="website"
        noindex={true}
      />

      <div className="container mx-auto px-6">
        <h1 className="text-3xl font-bold text-neutral-dark dark:text-white mb-8">
          Tag Management
        </h1>

        <div className="grid lg:grid-cols-3 gap-8">
          <div>
            <DndContext sensors={sensors} onDragEnd={handleDragEnd}>
              <TagList tags={tags} />
              <ContentList projects={projects} articles={articles} />
            </DndContext>
          </div>

          <div className="lg:col-span-2">
            <AssignmentDisplay projects={projects} articles={articles} tags={tags} />
          </div>
        </div>
      </div>
    </div>
  );
}
