import { useDraggable } from '@dnd-kit/core';
import { Tags } from 'lucide-react';

import { Tag } from '../../hooks/useTags';

interface TagListProps {
  tags: Tag[];
}

function DraggableTag({ tag }: { tag: Tag }) {
  const { attributes, listeners, setNodeRef, transform } = useDraggable({
    id: tag.id,
  });

  const style = transform
    ? {
        transform: `translate3d(${transform.x}px, ${transform.y}px, 0)`,
      }
    : undefined;

  return (
    <div
      ref={setNodeRef}
      style={style}
      {...listeners}
      {...attributes}
      className="bg-primary/10 dark:bg-primary/20 text-primary-dark dark:text-primary-light px-3 py-1.5 rounded-full text-sm cursor-move hover:bg-primary/20 dark:hover:bg-primary/30 transition-colors"
    >
      {tag.name}
    </div>
  );
}

export default function TagList({ tags }: TagListProps) {
  return (
    <div className="bg-white dark:bg-neutral-dark p-4 rounded-lg shadow">
      <div className="flex items-center gap-2 mb-4">
        <Tags className="w-5 h-5 text-primary dark:text-primary-light" />
        <h2 className="text-lg font-semibold">Available Tags</h2>
      </div>

      <div className="space-y-2">
        {tags.map(tag => (
          <DraggableTag key={tag.id} tag={tag} />
        ))}
      </div>
    </div>
  );
}
