import { useDroppable } from '@dnd-kit/core';
import { FileText, FolderGit2 } from 'lucide-react';

import type { ContentItem } from '../../types/common';

interface ContentListProps {
  projects: ContentItem[];
  articles: ContentItem[];
}

function DroppableItem({
  id,
  title,
  type,
}: {
  id: string;
  title: string;
  type: 'project' | 'article';
}) {
  const { isOver, setNodeRef } = useDroppable({
    id: `${type}:${id}`,
  });

  return (
    <div
      ref={setNodeRef}
      className={`p-3 rounded-lg border-2 transition-colors ${
        isOver ? 'border-primary bg-primary/10' : 'border-gray-200 dark:border-gray-700'
      }`}
    >
      <div className="flex items-center gap-2">
        {type === 'project' ? (
          <FolderGit2 className="w-4 h-4 text-primary dark:text-primary-light" />
        ) : (
          <FileText className="w-4 h-4 text-primary dark:text-primary-light" />
        )}
        <label htmlFor={`content-${type}-${id}`} className="truncate cursor-pointer">
          {title}
        </label>
        <input
          type="checkbox"
          id={`content-${type}-${id}`}
          name={`content-${type}-${id}`}
          className="sr-only"
          checked={isOver}
          readOnly
        />
      </div>
    </div>
  );
}

export default function ContentList({ projects, articles }: ContentListProps) {
  return (
    <div className="space-y-8">
      <div className="bg-white dark:bg-neutral-dark p-4 rounded-lg shadow">
        <h2 className="text-lg font-semibold mb-4">Projects</h2>
        <div className="space-y-2">
          {projects.map(project => (
            <DroppableItem key={project.id} id={project.id} title={project.title} type="project" />
          ))}
        </div>
      </div>

      <div className="bg-white dark:bg-neutral-dark p-4 rounded-lg shadow">
        <h2 className="text-lg font-semibold mb-4">Articles</h2>
        <div className="space-y-2">
          {articles.map(article => (
            <DroppableItem key={article.id} id={article.id} title={article.title} type="article" />
          ))}
        </div>
      </div>
    </div>
  );
}
