import { X } from 'lucide-react';

import type { Tag } from '../../hooks/useTags';
import { supabase } from '../../lib/supabase/client';
import type { ContentItem } from '../../types/common';
import { toast } from '../common/Toast';

interface AssignmentDisplayProps {
  projects: ContentItem[];
  articles: ContentItem[];
  tags: Tag[];
}

export default function AssignmentDisplay({ projects, articles, tags }: AssignmentDisplayProps) {
  async function handleRemoveTag(_type: 'project' | 'article', contentId: string, tagId: string) {
    try {
      const { data: content, error: fetchError } = await supabase
        .from('content')
        .select('tags')
        .eq('id', contentId)
        .single();

      if (fetchError) throw fetchError;

      // Remove tag from the array
      const updatedTags = (content.tags || []).filter(
        (t: string) => t !== tags.find(tag => tag.id === tagId)?.name
      );

      // Update content
      const { error: updateError } = await supabase
        .from('content')
        .update({ tags: updatedTags })
        .eq('id', contentId);

      if (updateError) throw updateError;

      toast.success('Tag removed successfully');
    } catch (error) {
      console.error('Error removing tag:', error);
      toast.error('Failed to remove tag');
    }
  }

  return (
    <div className="bg-white dark:bg-neutral-dark p-4 rounded-lg shadow">
      <h2 className="text-lg font-semibold mb-4">Current Assignments</h2>

      <div className="space-y-6">
        {projects.map(project => (
          <div key={project.id} className="space-y-2">
            <h3 className="font-medium">{project.title}</h3>
            <div className="flex flex-wrap gap-2">
              {project.tags?.map((tagName: string) => {
                const tag = tags.find(t => t.name === tagName);
                if (!tag) return null;

                return (
                  <div
                    key={tag.id}
                    className="flex items-center gap-1 bg-primary/10 dark:bg-primary/20 text-primary-dark dark:text-primary-light px-2 py-1 rounded-full text-sm"
                  >
                    {tag.name}
                    <button
                      onClick={() => handleRemoveTag('project', project.id, tag.id)}
                      className="hover:text-red-500 transition-colors"
                    >
                      <X className="w-3 h-3" />
                    </button>
                  </div>
                );
              })}
            </div>
          </div>
        ))}

        {articles.map(article => (
          <div key={article.id} className="space-y-2">
            <h3 className="font-medium">{article.title}</h3>
            <div className="flex flex-wrap gap-2">
              {article.tags?.map((tagName: string) => {
                const tag = tags.find(t => t.name === tagName);
                if (!tag) return null;

                return (
                  <div
                    key={tag.id}
                    className="flex items-center gap-1 bg-primary/10 dark:bg-primary/20 text-primary-dark dark:text-primary-light px-2 py-1 rounded-full text-sm"
                  >
                    {tag.name}
                    <button
                      onClick={() => handleRemoveTag('article', article.id, tag.id)}
                      className="hover:text-red-500 transition-colors"
                    >
                      <X className="w-3 h-3" />
                    </button>
                  </div>
                );
              })}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
